const form=document.querySelector('#join-form'),status=document.querySelector('#social-status'),people=document.querySelector('#social-people'),roomInput=document.querySelector('#room-code'),nameInput=document.querySelector('#visitor-name');
const invited=new URL(location.href).searchParams.get('room');let room=/^[a-zA-Z0-9_-]{8,48}$/.test(invited||'')?invited:'winter-plaza',joined=false,busy=false,gesture='',failures=0;roomInput.value=room;
try{nameInput.value=localStorage.getItem('winter-visitor-name')||'';}catch{}
async function request(path,body){const r=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(8000)});const data=await r.json();if(!r.ok){const e=Error(data.error||'연결을 다시 확인해 주세요.');e.status=r.status;throw e;}return data;}
function showPeople(list){people.replaceChildren();list=list.filter(p=>!window.isVisitorBlocked?.(p.id));for(const person of list){const li=document.createElement('li');li.textContent=person.name+(person.gesture==='wave'?' · 손 흔드는 중':'');const block=document.createElement('button');block.textContent='차단';block.dataset.blockVisitor=person.id;block.setAttribute('aria-label',person.name+' 차단');li.append(block);people.append(li);}window.dispatchEvent(new CustomEvent('lab:visitors',{detail:list}));}
form.addEventListener('submit',async e=>{e.preventDefault();if(joined){status.textContent='이미 함께 걷고 있어요. 다른 공간에 가려면 먼저 나와 주세요.';return;}const button=form.querySelector('button');button.disabled=true;status.textContent='같은 공간을 연결하고 있어요…';try{const data=await request('join',{name:nameInput.value,room:roomInput.value});room=data.room;joined=true;failures=0;try{localStorage.setItem('winter-visitor-name',data.name);}catch{}document.querySelector('#leave-room').hidden=false;status.textContent='함께 걷는 중 · 나 1명';window.labSocialJoined=true;await sync();}catch(e){status.textContent=e.message;}finally{button.disabled=false;}});
async function sync(){if(!joined||busy||document.hidden||!window.labPlayerState)return;busy=true;try{const a=window.labAppearance||{},data=await request('presence',{...window.labPlayerState,color:a.fur,accessory:a.accessory,gesture});gesture='';failures=0;showPeople(data.people);status.textContent='함께 걷는 중 · '+data.count+'명';}catch(e){failures++;if(e.status===401){joined=false;window.labSocialJoined=false;showPeople([]);}status.textContent=e.message+(joined?' · 연결을 다시 시도하고 있어요.':'');if(failures>2)showPeople([]);}finally{busy=false;}}
document.querySelector('#leave-room').onclick=async()=>{joined=false;window.labSocialJoined=false;showPeople([]);chatLog.replaceChildren();seenChats.clear();selfBubble.hidden=true;try{await request('leave',{});}catch{}status.textContent='혼자 느긋하게 걷는 중';document.querySelector('#leave-room').hidden=true;};
document.querySelector('#wave').onclick=()=>{if(!joined){status.textContent='입장한 뒤 인사할 수 있어요.';return;}gesture='wave';window.parkCelebrate?.();sync();};
document.querySelector('#new-room').onclick=()=>{if(joined){status.textContent='현재 공간에서 나온 뒤 새 공간을 만들어 주세요.';return;}room=crypto.randomUUID().replaceAll('-','').slice(0,16);roomInput.value=room;status.textContent='새 초대 공간을 만들었어요. 입장한 뒤 링크를 공유하세요.';};
document.querySelector('#copy-room').onclick=async()=>{const url=new URL(location.href);url.searchParams.set('room',roomInput.value);try{await navigator.clipboard.writeText(url.href);status.textContent='초대 링크를 복사했어요.';}catch{const link=document.querySelector('#invite-url');link.hidden=false;link.value=url.href;link.select();status.textContent='아래 주소를 복사해 주세요.';}};
setInterval(sync,1000);window.addEventListener('pagehide',()=>{if(joined)navigator.sendBeacon('/api/leave','{}');});

// Chat uses the same room/session as presence; text is never inserted as HTML.
const chatForm=document.querySelector('#chat-form'),chatInput=document.querySelector('#chat-input'),chatStatus=document.querySelector('#chat-status'),chatToggle=document.querySelector('#chat-toggle'),chatLog=document.querySelector('#chat-log'),selfBubble=document.querySelector('#self-bubble');
let chatJoining=null;const seenChats=new Set(),blocked=new Set();
function openChat(){chatForm.hidden=false;chatToggle.setAttribute('aria-expanded','true');window.dispatchEvent(new Event('lab:pause'));chatInput.focus();}
function closeChat(){chatForm.hidden=true;chatToggle.setAttribute('aria-expanded','false');chatInput.blur();}
chatToggle.onclick=()=>chatForm.hidden?openChat():closeChat();
window.addEventListener('keydown',e=>{if(e.isComposing||document.body.classList.contains('studio-open')||document.body.classList.contains('quiz-open'))return;if(e.key==='Escape'&&!chatForm.hidden){closeChat();return;}if(e.key==='Enter'&&e.target!==chatInput&&!e.target.closest?.('input,textarea,button,a,summary')){e.preventDefault();openChat();}});
function record(name,message,key){if(seenChats.has(key))return;seenChats.add(key);if(seenChats.size>300)seenChats.delete(seenChats.values().next().value);const row=document.createElement('p'),author=document.createElement('b');author.textContent=name+' ';row.append(author,document.createTextNode(message));row.dataset.expires=String(Date.now()+6500);chatLog.append(row);while(chatLog.children.length>20)chatLog.firstElementChild.remove();chatLog.scrollTop=chatLog.scrollHeight;}
async function ensureChatSession(){if(joined)return;if(!chatJoining)chatJoining=(async()=>{const data=await request('join',{name:nameInput.value||'겨울 손님',room:roomInput.value});room=data.room;joined=true;window.labSocialJoined=true;document.querySelector('#leave-room').hidden=false;await sync();})();try{await chatJoining;}finally{chatJoining=null;}}
chatForm.addEventListener('submit',async e=>{e.preventDefault();if(e.isComposing)return;const message=chatInput.value.trim();if(!message)return;const send=chatForm.querySelector('[type=submit]');send.disabled=true;try{await ensureChatSession();const data=await request('chat',{message});chatInput.value='';chatStatus.textContent='';record(data.name,data.message,'self:'+data.at);selfBubble.textContent=data.message;selfBubble.dataset.until=String(Date.now()+6500);selfBubble.hidden=false;closeChat();}catch(err){chatStatus.textContent=err.message;}finally{send.disabled=false;}});
window.addEventListener('lab:visitors',e=>{for(const p of e.detail)if(p.chat&&Date.now()-p.chatAt<12000&&!blocked.has(p.id))record(p.name,p.chat,p.id+':'+p.chatAt);});
window.isVisitorBlocked=id=>blocked.has(id);
people.addEventListener('click',e=>{const b=e.target.closest('[data-block-visitor]');if(!b)return;blocked.add(b.dataset.blockVisitor);b.closest('li')?.remove();sync();});

setInterval(()=>{for(const row of chatLog.children)if(Date.now()>Number(row.dataset.expires))row.remove();},500);
window.joinSharedActivity=ensureChatSession;
window.sharedRoom=()=>room;
